def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    prev_bids = []
    rich_threats = 0
    desperate_threats = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= 120:
                rich_threats += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_threats += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(float(prev['bid']))

    if not alive:
        return max(0.0, min(budget, 5.0))

    max_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    emergency = hp <= 2 or no_water >= 1
    fragile = hp <= 4

    if emergency:
        bid = max(0.95 * DAILY_SALARY, max_prev + 2.0)
        if supply <= 17:
            bid += 8.0
        return max(0.0, min(budget, bid))

    if fragile:
        bid = 0.68 * DAILY_SALARY + 0.18 * max_prev + 10.0 * scarcity
        if rich_threats >= 2:
            bid += 6.0
        return max(0.0, min(budget, bid))

    base = 0.34 * DAILY_SALARY + 0.10 * avg_prev + 8.0 * scarcity
    if supply >= 22:
        base -= 6.0
    elif supply <= 17:
        base += 8.0

    if max_prev >= 140:
        base = min(base, 0.42 * DAILY_SALARY)
    elif max_prev >= 90:
        base = max(base, 0.38 * DAILY_SALARY)

    if desperate_threats >= 2:
        base += 5.0

    if day >= 8 and hp >= 6 and no_water == 0:
        base -= 4.0

    reserve_floor = DAILY_SALARY * max(0, 10 - day) * 0.18
    if budget < reserve_floor:
        base *= 0.8

    return max(0.0, min(budget, base))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = day_context['supply']
    day = day_context['day']

    # Alive opponents only
    alive_opponents = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opponents.append(o)

    if my_status.get('budget', 0) <= 0:
        return 0.0

    # Read yesterday bids from previous_trace for immediate reaction
    yesterday_bids = []
    for o in alive_opponents:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    hp = my_status.get('hp', 0)
    budget = my_status.get('budget', 0)
    no_water_days = my_status.get('no_water_days', 0)

    # Base allocation logic: aim to secure water when we're at risk.
    risk = 0
    if hp <= 2:
        risk += 3
    if hp <= 5:
        risk += 2
    if no_water_days >= 2:
        risk += 2
    if no_water_days >= 3:
        risk += 2

    # Supply pressure: lower supply => higher chance of bidding war.
    # supply is between 15 and 25 in this meta-round.
    supply_pressure = 0
    if supply <= 18.0:
        supply_pressure = 3
    elif supply <= 20.0:
        supply_pressure = 2
    elif supply <= 22.0:
        supply_pressure = 1
    else:
        supply_pressure = 0

    # If opponents were willing to bid near/above our salary yesterday, increase bid.
    # Cindy/Eric showed high bids in the trace.
    threshold = DAILY_SALARY * 0.85
    if highest_prev_bid >= threshold:
        # Win more often when others are already spending.
        target = DAILY_SALARY * (0.65 + 0.15 * risk + 0.05 * supply_pressure)
    else:
        # Keep costs moderate.
        target = DAILY_SALARY * (0.45 + 0.12 * risk + 0.04 * supply_pressure)

    # Ensure we bid enough to potentially beat moderate bids, but cap to budget.
    # Add a small increment if there was a strong bid yesterday.
    if highest_prev_bid > 0:
        target = max(target, min(budget, highest_prev_bid * 0.55 + 10.0))

    # Cap target by budget and also by a practical ceiling to avoid bankrupting.
    # In this game, overbidding can lead to 0 budget; keep within ~1.2 salary.
    max_reasonable = min(budget, DAILY_SALARY * 1.2)
    bid = min(max_reasonable, max(0.0, target))

    # If we're very healthy and supply is high, reduce to preserve budget.
    if hp >= 8 and supply >= 22.0 and no_water_days == 0:
        bid = min(bid, DAILY_SALARY * 0.35)

    # If extremely risky, push closer to max_reasonable.
    if risk >= 5:
        bid = max(bid, DAILY_SALARY * 0.8)
        bid = min(bid, max_reasonable)

    # Final safety: never exceed budget
    if bid > budget:
        bid = float(budget)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if not alive_opponents:
        return min(my_status['budget'], 5.0)

    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 40.0

    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 0.9)

    if supply > 20:
        bid = min(my_status['budget'], avg_prev_bid * 0.8)
    else:
        bid = min(my_status['budget'], avg_prev_bid * 1.1)

    return max(1.0, bid)
